(function() {
    'use strict';

    class IntelOpsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'IntelOps: Competitive Intelligence';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    panel: 'round1Panel',
                    description: '<b>Mission:</b> You lead the Corporate Intelligence Unit at Solara Technologies (€4.1B consumer electronics, Barcelona). Your annual intelligence budget is €800k.<br><br><b>Context:</b> The smartphone accessory market is maturing (8% growth). Smart home is booming (20%+ growth) but giants are entering. Four competitors demand monitoring:<br><br>• <b>Nexus Ventures</b> (USA, €2.2B) — Premium positioning, strong R&D, strategic moves unclear<br>• <b>TechShield</b> (China, €1.8B) — Aggressive growth, pricing 30% below Solara<br>• <b>Ionix Electronics</b> (South Korea, €1.4B) — Fast follower, emerging AI capabilities<br>• <b>Quantum Devices</b> (USA, stealth) — VC-backed, ex-Apple team, suspected smart home focus<br><br><b>Decision:</b> Allocate your budget across five collection methods. Consider which methods best address your strategic questions about competitor moves in smart home, pricing threats, and emerging disruptors.'
                },
                {
                    titleKey: 'round2_title',
                    panel: 'round2Panel',
                    description: '<b>One month has passed.</b> Your intelligence team has deployed the collection architecture. Signals are arriving from the field.<br><br><b>Review the intelligence cards below</b>, then assess the threat level for each competitor (1=minimal, 10=critical). Consider signal reliability, patterns across sources, and contradictions.<br><br><b>Key question:</b> Which signals are actionable intelligence and which are noise? How confident are you in your overall assessment?'
                },
                {
                    titleKey: 'round3_title',
                    panel: 'round3Panel',
                    description: '<b>Competitive Shock:</b> Nexus Ventures just announced acquisition of Quantum Devices for €600M. They are integrating the team under a new brand: <b>Nexus Home</b>. Product launch in Q3 2025 (8 weeks). Nexus is investing €150M in product development, manufacturing, and go-to-market.<br><br><b>War Game Exercise:</b> Think like Nexus first — why acquire rather than build? Then think like Solara — how should you respond? Allocate your strategic response effort across four options.'
                },
                {
                    titleKey: 'round4_title',
                    panel: 'round4Panel',
                    description: '<b>Final Round: C-Suite Briefing.</b> Prepare your executive recommendation for the CEO and board of Solara Technologies.<br><br>Prioritize each strategic recommendation (1=Low Priority, 5=Critical Priority). Your briefing will be evaluated on:<br>• Evidence quality and attribution<br>• Recommendation specificity and feasibility<br>• Confidence calibration (not overconfident given evidence)<br>• Identification of key uncertainties'
                }
            ];

            this.SIGNALS = [
                { source: 'Patent DB', competitor: 'Nexus', content: 'Nexus filed patent on modular smart home hub architecture (Feb 2025, 5-person team)', reliability: 4 },
                { source: 'LinkedIn', competitor: 'Nexus', content: 'Nexus posted 12 open positions for smart home firmware engineers', reliability: 4 },
                { source: 'CES Trade Show', competitor: 'Nexus', content: 'Large booth at CES with smart home demo (previously had small booth)', reliability: 5 },
                { source: 'Press Release', competitor: 'Nexus', content: 'Nexus announced €80M Series C round for AI and smart home', reliability: 5 },
                { source: 'Gartner', competitor: 'Nexus', content: 'Analyst: Nexus is pivoting from accessories to smart home; margins will improve', reliability: 3 },
                { source: 'Marketing', competitor: 'TechShield', content: 'New Dragon Premium line announced targeting design-conscious consumers', reliability: 4 },
                { source: 'Supply Chain', competitor: 'TechShield', content: 'Expanded Vietnam facility by 30%; hiring for quality control', reliability: 4 },
                { source: 'Procurement', competitor: 'TechShield', content: 'Signed long-term supply agreement with TSMC', reliability: 3 },
                { source: 'LinkedIn', competitor: 'TechShield', content: 'Hired former Samsung product manager', reliability: 3 },
                { source: 'Patent DB', competitor: 'Ionix', content: 'Filed patent on AI-powered battery optimization (Jan 2025)', reliability: 4 },
                { source: 'Press Release', competitor: 'Ionix', content: 'Opened new R&D lab in Seoul (40 engineers) for next-gen hardware', reliability: 5 },
                { source: 'Crunchbase', competitor: 'Ionix', content: 'Acquired 25% stake in Korean AI startup Myounghae AI', reliability: 5 },
                { source: 'Analyst', competitor: 'Ionix', content: 'Ionix will enter smart home with AI-first approach by late 2025', reliability: 3 },
                { source: 'Real Estate', competitor: 'Quantum', content: 'New office lease in San Francisco (2,500 sq ft, larger than before)', reliability: 2 },
                { source: 'LinkedIn', competitor: 'Quantum', content: 'Hired 8 engineers from Apple hardware team (public posts)', reliability: 4 },
                { source: 'Funding', competitor: 'Quantum', content: 'Series B closing: €120M led by Sequoia Capital', reliability: 5 },
                { source: 'Blog', competitor: 'Quantum', content: 'Tech blogger visited office; 20% of floor is test lab', reliability: 2 },
                { source: 'HR Portal', competitor: 'Nexus', content: 'VP of HR position filled internally (routine churn)', reliability: 4 },
                { source: 'Social Media', competitor: 'TechShield', content: 'CEO posted vacation photos from Barcelona', reliability: 1 },
                { source: 'Conference', competitor: 'Ionix', content: 'CTO gave keynote on sustainability at industry conference', reliability: 3 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 800000,
                    totalScore: 0,
                    roundScores: [],
                    threatLevel: 0,
                    intelConfidence: 0,
                    r1TradeShows: 0,
                    r1Patents: 0,
                    r1Suppliers: 0,
                    r1Analysts: 0,
                    r1Digital: 0,
                    r2NexusThreat: 0,
                    r2TechShieldThreat: 0,
                    r2IonixThreat: 0,
                    r2QuantumThreat: 0,
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    allocation1: 20,
                    allocation2: 20,
                    allocation3: 20,
                    allocation4: 20,
                    allocation5: 20
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.description;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                var titleText = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';
                if (titleText && titleText !== round.titleKey) {
                    titleEl.textContent = titleText;
                }
            }

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) {
                    panel.style.display = (panels[i] === round.panel) ? 'block' : 'none';
                }
            }

            if (idx === 1) {
                this._renderSignalCards();
            }

            this._setupAllocationListeners(idx);
        }

        _renderSignalCards() {
            var container = document.getElementById('signalCardsContainer');
            if (!container) return;
            var html = '';
            for (var i = 0; i < this.SIGNALS.length; i++) {
                var s = this.SIGNALS[i];
                var stars = '';
                for (var j = 0; j < 5; j++) {
                    stars += j < s.reliability ? '★' : '☆';
                }
                html += '<div class="intelops-sim-signal-card">';
                html += '<div class="signal-source">' + s.source + ' | ' + s.competitor + '</div>';
                html += '<div class="signal-content">' + s.content + '</div>';
                html += '<div class="signal-reliability">Reliability: ' + stars + '</div>';
                html += '</div>';
            }
            container.innerHTML = html;
        }

        _setupAllocationListeners(roundIdx) {
            var self = this;
            if (roundIdx === 0) {
                var ids = ['tradeShowInput', 'patentInput', 'supplierInput', 'analystInput', 'digitalInput'];
                ids.forEach(function(id) {
                    var el = document.getElementById(id);
                    if (el) {
                        el.removeEventListener('input', self._updateR1Total);
                        el.addEventListener('input', function() { self._updateR1Total(); });
                    }
                });
                self._updateR1Total();
            } else if (roundIdx === 2) {
                var rIds = ['rdAccelInput', 'partnerInput', 'acquisitionInput', 'defensiveInput'];
                rIds.forEach(function(id) {
                    var el = document.getElementById(id);
                    if (el) {
                        el.removeEventListener('input', self._updateR3Total);
                        el.addEventListener('input', function() { self._updateR3Total(); });
                    }
                });
                self._updateR3Total();
            }
        }

        _updateR1Total() {
            var ids = ['tradeShowInput', 'patentInput', 'supplierInput', 'analystInput', 'digitalInput'];
            var total = 0;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) total += parseInt(el.value) || 0;
            });
            var display = document.getElementById('allocationTotal');
            if (display) {
                display.textContent = total + '%';
                display.style.color = total === 100 ? '#4caf50' : '#f44336';
            }
        }

        _updateR3Total() {
            var ids = ['rdAccelInput', 'partnerInput', 'acquisitionInput', 'defensiveInput'];
            var total = 0;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) total += parseInt(el.value) || 0;
            });
            var display = document.getElementById('responseTotal');
            if (display) {
                display.textContent = total + '%';
                display.style.color = total === 100 ? '#4caf50' : '#f44336';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var round = window.mySimulation.state.currentPeriod || 1;

            if (round === 1) {
                var ts = document.getElementById('tradeShowInput');
                var pt = document.getElementById('patentInput');
                var sp = document.getElementById('supplierInput');
                var an = document.getElementById('analystInput');
                var dg = document.getElementById('digitalInput');
                decisions.tradeShows = parseInt(ts ? ts.value : 20);
                decisions.patents = parseInt(pt ? pt.value : 20);
                decisions.suppliers = parseInt(sp ? sp.value : 20);
                decisions.analysts = parseInt(an ? an.value : 20);
                decisions.digital = parseInt(dg ? dg.value : 20);
                var total = decisions.tradeShows + decisions.patents + decisions.suppliers + decisions.analysts + decisions.digital;
                if (total !== 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('allocation_warning'), 'warning'
                    );
                    return false;
                }
                if (decisions.tradeShows < 0 || decisions.patents < 0 || decisions.suppliers < 0 || decisions.analysts < 0 || decisions.digital < 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('negative_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 2) {
                var nx = document.getElementById('nexusThreatInput');
                var tc = document.getElementById('techshieldThreatInput');
                var ix = document.getElementById('ionixThreatInput');
                var qd = document.getElementById('quantumThreatInput');
                var cf = document.getElementById('confidenceInput');
                decisions.nexusThreat = parseInt(nx ? nx.value : 5);
                decisions.techshieldThreat = parseInt(tc ? tc.value : 5);
                decisions.ionixThreat = parseInt(ix ? ix.value : 5);
                decisions.quantumThreat = parseInt(qd ? qd.value : 5);
                decisions.confidence = parseInt(cf ? cf.value : 3);
                if (decisions.nexusThreat < 1 || decisions.nexusThreat > 10 ||
                    decisions.techshieldThreat < 1 || decisions.techshieldThreat > 10 ||
                    decisions.ionixThreat < 1 || decisions.ionixThreat > 10 ||
                    decisions.quantumThreat < 1 || decisions.quantumThreat > 10) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('threat_warning'), 'warning'
                    );
                    return false;
                }
                if (decisions.confidence < 1 || decisions.confidence > 5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('confidence_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 3) {
                var rd = document.getElementById('rdAccelInput');
                var pr = document.getElementById('partnerInput');
                var aq = document.getElementById('acquisitionInput');
                var df = document.getElementById('defensiveInput');
                decisions.rdAccel = parseInt(rd ? rd.value : 25);
                decisions.partnerships = parseInt(pr ? pr.value : 25);
                decisions.acquisition = parseInt(aq ? aq.value : 25);
                decisions.defensive = parseInt(df ? df.value : 25);
                var rTotal = decisions.rdAccel + decisions.partnerships + decisions.acquisition + decisions.defensive;
                if (rTotal !== 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('response_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 4) {
                var sh = document.getElementById('recSmartHomeInput');
                var oe = document.getElementById('recPartnerOEMInput');
                var dv = document.getElementById('recDiversifyInput');
                var ac = document.getElementById('recAcquireInput');
                var bc = document.getElementById('briefConfidenceInput');
                decisions.recSmartHome = parseInt(sh ? sh.value : 3);
                decisions.recPartnerOEM = parseInt(oe ? oe.value : 3);
                decisions.recDiversify = parseInt(dv ? dv.value : 3);
                decisions.recAcquire = parseInt(ac ? ac.value : 3);
                decisions.briefConfidence = parseInt(bc ? bc.value : 3);
                if (decisions.recSmartHome < 1 || decisions.recSmartHome > 5 ||
                    decisions.recPartnerOEM < 1 || decisions.recPartnerOEM > 5 ||
                    decisions.recDiversify < 1 || decisions.recDiversify > 5 ||
                    decisions.recAcquire < 1 || decisions.recAcquire > 5 ||
                    decisions.briefConfidence < 1 || decisions.briefConfidence > 5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('priority_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var score = 0;
            var maxScore = 25;
            var feedback = '';

            if (round === 1) {
                var vals = [d.tradeShows, d.patents, d.suppliers, d.analysts, d.digital];
                var nonZero = vals.filter(function(v) { return v > 0; }).length;
                var diversityScore = nonZero * 2;
                var patentBonus = d.patents >= 15 ? 3 : (d.patents >= 10 ? 2 : 0);
                var supplierBonus = d.suppliers >= 15 ? 3 : (d.suppliers >= 10 ? 2 : 0);
                var maxAlloc = Math.max.apply(null, vals);
                var concentrationPenalty = maxAlloc > 50 ? -3 : (maxAlloc > 40 ? -1 : 0);
                var digitalBonus = d.digital >= 10 ? 1 : 0;
                score = Math.min(maxScore, Math.max(0, diversityScore + patentBonus + supplierBonus + concentrationPenalty + digitalBonus + 10));
                state.domainState.r1TradeShows = d.tradeShows;
                state.domainState.r1Patents = d.patents;
                state.domainState.r1Suppliers = d.suppliers;
                state.domainState.r1Analysts = d.analysts;
                state.domainState.r1Digital = d.digital;
                if (nonZero === 5) feedback = 'Well-diversified intelligence portfolio.';
                else if (nonZero <= 2) feedback = 'Too concentrated. Diversify your collection methods.';
                else feedback = 'Reasonable allocation. Consider more diversification.';
            } else if (round === 2) {
                var idealNexus = 9;
                var idealTechShield = 5;
                var idealIonix = 6;
                var idealQuantum = 8;
                var nexusDiff = Math.abs(d.nexusThreat - idealNexus);
                var techDiff = Math.abs(d.techshieldThreat - idealTechShield);
                var ionixDiff = Math.abs(d.ionixThreat - idealIonix);
                var quantumDiff = Math.abs(d.quantumThreat - idealQuantum);
                var totalDiff = nexusDiff + techDiff + ionixDiff + quantumDiff;
                var accuracyScore = Math.max(0, 15 - totalDiff);
                var r1PatentAlloc = state.domainState.r1Patents || 0;
                var r1SupplierAlloc = state.domainState.r1Suppliers || 0;
                var collectionBonus = 0;
                if (r1PatentAlloc >= 15) collectionBonus += 2;
                if (r1SupplierAlloc >= 15) collectionBonus += 2;
                var confCalibration = 0;
                if (totalDiff <= 6 && d.confidence >= 4) confCalibration = 2;
                else if (totalDiff <= 6 && d.confidence <= 2) confCalibration = -1;
                else if (totalDiff > 10 && d.confidence >= 4) confCalibration = -3;
                else if (totalDiff > 10 && d.confidence <= 2) confCalibration = 2;
                else confCalibration = 1;
                score = Math.min(maxScore, Math.max(0, accuracyScore + collectionBonus + confCalibration));
                state.domainState.r2NexusThreat = d.nexusThreat;
                state.domainState.r2TechShieldThreat = d.techshieldThreat;
                state.domainState.r2IonixThreat = d.ionixThreat;
                state.domainState.r2QuantumThreat = d.quantumThreat;
                state.domainState.intelConfidence = d.confidence;
                state.domainState.threatLevel = Math.round((d.nexusThreat + d.techshieldThreat + d.ionixThreat + d.quantumThreat) / 4);
                if (totalDiff <= 4) feedback = 'Excellent signal analysis. Threat assessments closely match reality.';
                else if (totalDiff <= 8) feedback = 'Good analysis but some assessments are off. Recheck conflicting signals.';
                else feedback = 'Significant gaps in threat assessment. Signal-to-noise filtering needs work.';
            } else if (round === 3) {
                var rdScore = 0;
                if (d.rdAccel >= 30 && d.rdAccel <= 50) rdScore = 8;
                else if (d.rdAccel >= 20 && d.rdAccel <= 60) rdScore = 5;
                else rdScore = 2;
                var partnerScore = 0;
                if (d.partnerships >= 20 && d.partnerships <= 40) partnerScore = 6;
                else if (d.partnerships >= 10) partnerScore = 3;
                else partnerScore = 1;
                var acqScore = 0;
                if (d.acquisition >= 10 && d.acquisition <= 30) acqScore = 5;
                else if (d.acquisition > 30) acqScore = 2;
                else acqScore = 3;
                var defPenalty = 0;
                if (d.defensive > 40) defPenalty = -3;
                else if (d.defensive > 25) defPenalty = -1;
                var balanceBonus = 0;
                var rVals = [d.rdAccel, d.partnerships, d.acquisition, d.defensive];
                var rNonZero = rVals.filter(function(v) { return v > 0; }).length;
                if (rNonZero >= 3) balanceBonus = 2;
                score = Math.min(maxScore, Math.max(0, rdScore + partnerScore + acqScore + defPenalty + balanceBonus));
                if (d.rdAccel >= 30) feedback = 'Strong offensive posture. R&D acceleration is the right priority.';
                else if (d.defensive >= 40) feedback = 'Too defensive. Nexus is moving fast; defense alone is insufficient.';
                else feedback = 'Balanced response. Consider whether R&D deserves more emphasis.';
            } else if (round === 4) {
                var smartHomeScore = d.recSmartHome >= 4 ? 5 : (d.recSmartHome >= 3 ? 3 : 1);
                var oemScore = d.recPartnerOEM >= 3 ? 4 : 2;
                var diversifyScore2 = d.recDiversify >= 3 ? 3 : 1;
                var acqRecScore = d.recAcquire >= 2 && d.recAcquire <= 4 ? 3 : 1;
                var prevAccuracy = state.domainState.roundScores.length >= 2 ? state.domainState.roundScores[1] : 12;
                var briefConfScore = 0;
                if (prevAccuracy >= 18 && d.briefConfidence >= 4) briefConfScore = 5;
                else if (prevAccuracy >= 18 && d.briefConfidence <= 2) briefConfScore = 2;
                else if (prevAccuracy < 12 && d.briefConfidence >= 4) briefConfScore = 0;
                else if (prevAccuracy < 12 && d.briefConfidence <= 2) briefConfScore = 4;
                else briefConfScore = 3;
                score = Math.min(maxScore, Math.max(0, smartHomeScore + oemScore + diversifyScore2 + acqRecScore + briefConfScore));
                if (d.recSmartHome >= 4 && d.recPartnerOEM >= 3) feedback = 'Strong briefing. Smart home acceleration with OEM partnerships is the right call.';
                else if (d.recSmartHome <= 2) feedback = 'Underweighting smart home is risky given competitive moves.';
                else feedback = 'Reasonable recommendations. Could be more decisive on smart home priority.';
            }

            state.domainState.totalScore += score;
            state.domainState.roundScores.push(score);
            state.domainState.scoreHistory.push(score);
            var _played = state.domainState.roundScores.length;
            var _pct = _played > 0 ? Math.round(state.domainState.totalScore / (_played * 25) * 100) : 0;
            state.domainState.score = Math.max(0, Math.min(100, _pct));
            state.domainState.performance = { overallScore: state.domainState.score, rating: (_pct >= 85 ? 'Master Strategist' : _pct >= 70 ? 'Senior Intelligence Officer' : _pct >= 55 ? 'Competent Analyst' : _pct >= 40 ? 'Junior Analyst' : 'Beginner Analyst'), rawScore: state.domainState.totalScore };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: round,
                roundScore: score,
                maxScore: maxScore,
                pctScore: Math.round((score / maxScore) * 100),
                totalScore: state.domainState.totalScore,
                feedback: feedback
            };
        }

