        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var maxPossible = scores.length * 25;
            var pct = Math.round((totalScore / maxPossible) * 100);

            var performance = 'Beginner Analyst';
            if (pct >= 85) performance = 'Master Strategist';
            else if (pct >= 70) performance = 'Senior Intelligence Officer';
            else if (pct >= 55) performance = 'Competent Analyst';
            else if (pct >= 40) performance = 'Junior Analyst';

            var insights = [];
            if (scores.length >= 1 && scores[0] >= 20) insights.push('Excellent intelligence architecture design.');
            if (scores.length >= 1 && scores[0] < 12) insights.push('Intelligence architecture was too concentrated. Diversify collection methods.');
            if (scores.length >= 2 && scores[1] >= 20) insights.push('Outstanding signal detection and threat calibration.');
            if (scores.length >= 2 && scores[1] < 12) insights.push('Signal-to-noise filtering needs improvement. Weight high-reliability sources more.');
            if (scores.length >= 3 && scores[2] >= 20) insights.push('Strong strategic response to competitive shock.');
            if (scores.length >= 3 && scores[2] < 12) insights.push('War game response was too reactive. Prioritize offensive moves.');
            if (scores.length >= 4 && scores[3] >= 20) insights.push('Compelling C-suite briefing with well-calibrated recommendations.');
            if (scores.length >= 4 && scores[3] < 12) insights.push('Briefing lacked decisiveness. Leaders need clear, prioritized recommendations.');

            return {
                overallScore: pct,
                score: pct,
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: pct,
                performance: performance,
                insights: insights
            };
